def countSubsetsWithinBudget(nums, budget):
    def sums(arr):
        s = [0]
        for x in arr:
            s = s + [v + x for v in s]
        s.sort()
        return s

    h = len(nums) // 2
    left = sums(nums[:h])
    right = sums(nums[h:])
    j = len(right)
    total = 0
    for a in left:
        if a > budget:
            break
        while j > 0 and right[j - 1] + a > budget:
            j -= 1
        total += j
    return total
